for nn in range(_sage_const_60 ):
    inner.append(ZZ(sum(binomial(nn,k)**_sage_const_2  * binomial(nn+k,nn) * binomial(nn+_sage_const_2 *k,nn)
                        for k in range(nn+_sage_const_1 ))))
